import React, { useEffect, useRef, useState } from "react";
import { api } from "./api/client";
import { AdminLogin } from "./components/AdminLogin";
import { AdminPage } from "./components/AdminPage";
import { CafeteriaPage } from "./components/CafeteriaPage";
import { ARView } from "./components/ARView";
import { HomePage } from "./components/HomePage";
import { RouteGuide } from "./components/RouteGuide";
import { SurveyForm } from "./components/SurveyForm";
import { AnnouncementPop } from "./components/AnnouncementPop";
import { CompassPermissionPop } from "./components/CompassPermissionPop";
import { useUser } from "./hooks/useUser";
import { useCompassPermission, compassNeedsPermission } from "./hooks/useCompass";
import { Announcement, Cafeteria, Destination, IndoorTransition, Link, Node, NodeDetour, Photo, RouteResponse, Setting } from "./types";
import { CAFETERIA_CONGESTION_LABELS, CAFETERIA_CONGESTION_COLORS } from "./utils/congestion";
import "./index.css";

// パスで表示アプリを切り替える（/admin=管理者, /cafeteria=食堂編集, それ以外=ユーザー）
const isAdminPath = window.location.pathname.startsWith("/admin");
const isCafeteriaPath = window.location.pathname.startsWith("/cafeteria");

// ── 管理者アプリ ──────────────────────────────────────────────
function AdminApp() {
  const [token, setToken] = useState(() => localStorage.getItem("admin_token") ?? "");
  const [role, setRole] = useState(() => localStorage.getItem("admin_role") ?? "");
  const [nodes, setNodes] = useState<Node[]>([]);
  const [links, setLinks] = useState<Link[]>([]);

  useEffect(() => {
    // 食堂編集用アカウントはノード/リンクを使わないので取得しない
    if (!token || role === "cafeteria") return;
    Promise.all([api.nodes.list(), api.links.list()])
      .then(([n, l]) => { setNodes(n); setLinks(l); })
      .catch(() => {});
  }, [token, role]);

  const handleLogin = (t: string, r: string) => { setToken(t); setRole(r); };

  const handleLogout = () => {
    localStorage.removeItem("admin_token");
    localStorage.removeItem("admin_role");
    setToken("");
    setRole("");
  };

  if (!token) return <AdminLogin onLogin={handleLogin} />;

  // 食堂編集用アカウントは食堂の混雑度だけを編集できる専用画面を表示する
  if (role === "cafeteria") return <CafeteriaPage onLogout={handleLogout} />;

  return (
    <div className="app">
      <header className="app-header">
        <h1>管理画面</h1>
        <nav>
          <button onClick={handleLogout}>ログアウト</button>
        </nav>
      </header>
      <AdminPage
        nodes={nodes}
        links={links}
        onNodeCreated={(node) => setNodes((p) => [...p, node])}
        onNodeUpdated={(node) => setNodes((p) => p.map((n) => n.id === node.id ? node : n))}
        onNodeDeleted={(id) => setNodes((p) => p.filter((n) => n.id !== id))}
        onLinkCreated={(link) => setLinks((p) => [...p, link])}
        onLinkUpdated={(link) => setLinks((p) => p.map((l) => l.id === link.id ? link : l))}
        onLinkDeleted={(id) => setLinks((p) => p.filter((l) => l.id !== id))}
        onPhotoUploaded={(linkId, photo) =>
          setLinks((p) => p.map((l) => l.id === linkId ? { ...l, photos: [...(l.photos ?? []), photo] } : l))}
        onPhotoDeleted={(linkId, photoId) =>
          setLinks((p) => p.map((l) => l.id === linkId ? { ...l, photos: (l.photos ?? []).filter((ph) => ph.id !== photoId) } : l))}
        onPhotoReordered={(linkId, photos) =>
          setLinks((p) => p.map((l) => l.id === linkId ? { ...l, photos } : l))}
      />
    </div>
  );
}

// ── 食堂編集アプリ（独立URL /cafeteria）──────────────────────────
// 食堂編集用アカウントでログインし、食堂の混雑度だけを編集する専用画面。
// 管理者パスワードでもログインできる（admin トークンも食堂APIを使えるため）。
function CafeteriaApp() {
  const [token, setToken] = useState(() => localStorage.getItem("admin_token") ?? "");

  const handleLogin = (t: string) => setToken(t);

  const handleLogout = () => {
    localStorage.removeItem("admin_token");
    localStorage.removeItem("admin_role");
    setToken("");
  };

  if (!token) return <AdminLogin onLogin={handleLogin} />;
  return <CafeteriaPage onLogout={handleLogout} />;
}

// ── ユーザーアプリ ────────────────────────────────────────────
type Screen = "home" | "route" | "ar" | "survey";

// URL パスと画面の対応（ハッシュを使わないパス方式のルーティング）
const screenToPath: Record<Screen, string> = {
  home: "/", route: "/route", ar: "/ar", survey: "/survey",
};
function pathToScreen(path: string): Screen {
  if (path === "/route") return "route";
  if (path === "/ar") return "ar";
  if (path === "/survey") return "survey";
  return "home";
}

function UserApp() {
  useUser();
  const [nodes, setNodes] = useState<Node[]>([]);
  const [links, setLinks] = useState<Link[]>([]);
  const [destinations, setDestinations] = useState<Destination[]>([]);
  const [nodeDetours, setNodeDetours] = useState<NodeDetour[]>([]);
  const [indoorTransitions, setIndoorTransitions] = useState<IndoorTransition[]>([]);
  const [cafeterias, setCafeterias] = useState<Cafeteria[]>([]);
  // 初期画面は URL から決める。ただし route はルートデータが無いと表示できないため、
  // コールドロードで /route を開いた場合は home にフォールバックする。
  const [screen, setScreen] = useState<Screen>(() => {
    const s = pathToScreen(window.location.pathname);
    return s === "route" ? "home" : s;
  });
  const [route, setRoute] = useState<RouteResponse | null>(null);
  // お知らせPOP（アプリを開いた最初に、カメラ/コンパス許可より前に表示）
  const [announcement, setAnnouncement] = useState<Announcement | null>(null);
  const [popDismissed, setPopDismissed] = useState(false);
  // お知らせの取得が完了したか（完了後にコンパス許可ポップアップの表示判定を行う）
  const [announcementChecked, setAnnouncementChecked] = useState(false);
  // コンパス許可ポップアップを今のホーム滞在中に閉じたか（＝一時的に隠すだけ）。
  // 永続保存はしない。ホーム画面に来るたびにリセットして、許可が済むまで再表示する。
  const [compassPopDismissed, setCompassPopDismissed] = useState(false);
  // コンパス許可状態を購読（iOS 未許可のときだけポップアップを出すため）
  const compass = useCompassPermission();
  // アンケートをアプリ内操作で開いたか（true のとき閉じるは履歴を戻す）
  const openedSurveyInApp = useRef(false);
  const [loadError, setLoadError] = useState("");
  const [settings, setSettings] = useState<Setting>({
    id: 1, map_north_offset: 0,
    reroute_visibility: true, reroute_incident: true,
    reroute_congestion: true, reroute_other: true,
    stamp_url: "",
    show_cafeteria_congestion: true, show_ar_button: true,
    survey_url: "", default_destination_id: null,
  });

  useEffect(() => {
    // 経路ネットワーク（ノード＋リンク）はインターフェース化した専用エンドポイントで一括取得する。
    // 屋内案内（indoorTransitions）も併せて取得する。
    Promise.all([api.routeNetwork.get(), api.nodeDetours.list(), api.destinations.list(), api.indoorTransitions.list()])
      .then(([net, d, dest, it]) => { setNodes(net.nodes); setLinks(net.links); setNodeDetours(d); setDestinations(dest); setIndoorTransitions(it); })
      .catch((e) => setLoadError(e.message));
  }, []);

  useEffect(() => {
    api.settings.get().then(setSettings).catch(() => {});
    api.cafeterias.list().then(setCafeterias).catch(() => {});
  }, []);

  // お知らせPOPを取得。取得完了後（お知らせを閉じた後）にコンパス許可ポップアップの表示判定を行う。
  useEffect(() => {
    api.announcements.getActive()
      .then((a: Announcement | null) => { if (a) setAnnouncement(a); })
      .catch(() => {})
      .finally(() => setAnnouncementChecked(true));
  }, []);

  const dismissPop = () => setPopDismissed(true);

  // ホーム画面かつ、お知らせPOPが閉じていて、iOSで方位センサー未許可（prompt）で、
  // この滞在中にまだ閉じていないときにコンパス許可ポップアップを出す。
  // コンパスがオン（granted）になれば permission が prompt でなくなり自動的に出なくなる。
  // ※カメラはブラウザ標準ダイアログが必ず出るため前置きは出さず、実際に使う場面で1回だけ許可を求める。
  const announcementOpen = !!announcement && !popDismissed;
  const showCompassPop =
    screen === "home" && announcementChecked && !announcementOpen &&
    compassNeedsPermission() && compass.permission === "prompt" && !compassPopDismissed;

  // 位置情報は、お知らせを閉じてコンパス許可の選択（有効にする／今はしない）が済んでから取得する。
  const locationAllowed = announcementChecked && !announcementOpen && !showCompassPop;

  // ホーム画面に来るたびに一時非表示をリセットし、オンにされていない限り再表示する。
  useEffect(() => {
    if (screen === "home") setCompassPopDismissed(false);
  }, [screen]);

  // 閉じるのはこの滞在中だけ隠す（次にホームへ来たら再表示される）。
  const closeCompassPop = () => setCompassPopDismissed(true);
  const enableCompass = () => {
    // このクリックはユーザー操作なので、ここで iOS のコンパス許可要求を発火できる。
    compass.requestPermission();
    closeCompassPop();
  };

  // 初期表示が URL と食い違う場合は URL 側を画面に合わせる（例: コールドロードの /route → home）
  useEffect(() => {
    const desired = screenToPath[screen];
    if (window.location.pathname !== desired) {
      window.history.replaceState(null, "", desired);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ブラウザの戻る/進むで URL が変わったら画面も追従する。
  useEffect(() => {
    const onPop = () => {
      let s = pathToScreen(window.location.pathname);
      if (s === "route" && !route) s = "home"; // ルートデータが無ければ home
      setScreen(s);
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, [route]);

  // 画面遷移。URL も同時に更新する（push でブラウザ履歴に積む／replace で置換）。
  const navigate = (s: Screen, opts?: { replace?: boolean }) => {
    const path = screenToPath[s];
    if (window.location.pathname !== path) {
      if (opts?.replace) window.history.replaceState(null, "", path);
      else window.history.pushState(null, "", path);
    }
    setScreen(s);
  };

  const handleRouteReady = (r: RouteResponse) => {
    setRoute(r);
    navigate("route");
  };

  // 到着カードのボタンからアプリ内アンケート（/survey）へ遷移する。
  const openSurvey = () => {
    openedSurveyInApp.current = true;
    navigate("survey");
  };

  // アンケートを閉じる。アプリ内で開いた場合は履歴を戻して元画面へ、
  // 直接 /survey を開いた場合は home へ置換で戻る。
  const closeSurvey = () => {
    if (openedSurveyInApp.current) {
      openedSurveyInApp.current = false;
      window.history.back();
    } else {
      navigate("home", { replace: true });
    }
  };

  return (
    <div className="app">
      {/* お知らせPOP（最初に表示。カメラ/コンパス許可より前） */}
      {announcement && !popDismissed && (
        <AnnouncementPop announcement={announcement} onClose={dismissPop} />
      )}

      {/* お知らせを閉じた直後、iOSで方位センサー未許可のときだけコンパス許可ポップアップを出す */}
      {showCompassPop && (
        <CompassPermissionPop onEnable={enableCompass} onDismiss={closeCompassPop} />
      )}

      <header className="app-header">
        {/* タイトルは非表示。ホームへ戻る導線は「← 戻る」「AR」ボタンで担保。
            space-between の右寄せレイアウトを保つため空のスペーサーを置く。 */}
        <span className="header-spacer" onClick={() => navigate("home")} />
        <div className="header-actions">
          {settings.show_cafeteria_congestion && cafeterias.map((cafe) => (
            <span key={cafe.id} className="cafeteria-congestion" title={`${cafe.name}の混雑度`}>
              <span className="cafeteria-congestion-label">{cafe.name}</span>
              <span
                className="cafeteria-congestion-badge"
                style={{ background: CAFETERIA_CONGESTION_COLORS[cafe.congestion_level] ?? CAFETERIA_CONGESTION_COLORS[0] }}
              >
                {CAFETERIA_CONGESTION_LABELS[cafe.congestion_level] ?? "不明"}
              </span>
            </span>
          ))}
          {settings.stamp_url && (
            <a
              className="stamp-button"
              href={settings.stamp_url}
              target="_blank"
              rel="noopener noreferrer"
            >
              スタンプ
            </a>
          )}
          {screen === "home" && settings.show_ar_button && (
            <button onClick={() => navigate("ar")}>AR</button>
          )}
          {screen !== "home" && screen !== "survey" && (
            <button onClick={() => navigate("home")}>← 戻る</button>
          )}
        </div>
      </header>

      {loadError && (
        <div className="global-error" onClick={() => setLoadError("")}>
          {loadError} ✕
        </div>
      )}

      {screen === "home" && (
        <HomePage
          nodes={nodes}
          links={links}
          destinations={destinations}
          nodeDetours={nodeDetours}
          indoorTransitions={indoorTransitions}
          settings={settings}
          surveyUrl={settings.survey_url}
          onOpenSurvey={openSurvey}
          allowLocation={locationAllowed}
        />
      )}

      {screen === "ar" && <ARView nodes={nodes} />}

      {/* 道案内は survey を開いている間も裏で残す（アンケートは上に重ねて表示） */}
      {(screen === "route" || screen === "survey") && route && (
        <RouteGuide
          route={route}
          nodes={nodes}
          links={links}
          nodeDetours={nodeDetours}
          indoorTransitions={indoorTransitions}
          onClose={() => navigate("home")}
          settings={settings}
          onReroute={(newRoute) => setRoute(newRoute)}
          onOpenSurvey={openSurvey}
        />
      )}

      {screen === "survey" && (
        <SurveyForm fallbackUrl={settings.survey_url} onClose={closeSurvey} />
      )}
    </div>
  );
}

// ── ルートエントリ ────────────────────────────────────────────
export default function App() {
  if (isAdminPath) return <AdminApp />;
  if (isCafeteriaPath) return <CafeteriaApp />;
  return <UserApp />;
}
